def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    enemies = observation.get('opponent_position', [])
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    dx, dy = 0, 0
    # Helper to check safety of a cell
    def safe(nx, ny):
        if not (0 <= nx < width and 0 <= ny < height):
            return False
        if (nx, ny) in obstacles:
            return False
        for ox, oy in enemies:
            if (ox == nx and oy == ny):
                return False
        return True
    # Find closest resource
    target = None
    min_dist = float('inf')
    for rx, ry in resources:
        dist = abs(rx - x) + abs(ry - y)
        if dist < min_dist:
            min_dist = dist
            target = (rx, ry)
    # Move towards resource if found
    if target:
        tx, ty = target
        dx, dy = (tx - x), (ty - y)
        if abs(dx) > abs(dy):
            step = (1 if dx > 0 else -1, 0)
        elif dy != 0:
            step = (0, 1 if dy > 0 else -1)
        else:
            step = (0, 0)
        nx, ny = x + step[0], y + step[1]
        if safe(nx, ny):
            return [step[0], step[1]]
    # Otherwise, move randomly to a safe cell
    for ddx, ddy in [(1,0), (-1,0), (0,1), (0,-1)]:
        nx, ny = x + ddx, y + ddy
        if safe(nx, ny):
            return [ddx, ddy]
    # No safe moves, stay put
    return [0, 0]
